delete from country_flag_history where id = 2249 and iso_code = 'sv';
update country_flag_history set label_fr = 'Provinces-Unies d''Amérique centrale', label_en = 'United Provinces of Central America', notes_fr = 'Le Salvador rejoint les Provinces-Unies d''Amérique centrale, dont il reprend les bandes bleu-blanc-bleu.', notes_en = 'El Salvador joined the United Provinces of Central America and took up their blue-white-blue stripes.' where id = 2489 and iso_code = 'sv';
update country_flag_history set label_fr = 'République fédérale d''Amérique centrale', label_en = 'Federal Republic of Central America', notes_fr = 'Fervent défenseur de la fédération, le Salvador en arbore le drapeau jusqu''à sa dissolution.', notes_en = 'A staunch supporter of the federation, El Salvador flew its flag until it was dissolved.' where id = 2490 and iso_code = 'sv';
update country_flag_history set label_fr = 'État du Salvador (1841-1865)', label_en = 'State of El Salvador (1841–1865)', notes_fr = 'Après la fin de la fédération, le Salvador garde les bandes bleu-blanc-bleu avec ses propres armes.', notes_en = 'After the federation ended, El Salvador kept the blue-white-blue stripes with its own arms.' where id = 2491 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (avril 1865)', label_en = 'Republic of El Salvador (April 1865)', notes_fr = 'Version éphémère adoptée en avril 1865.', notes_en = 'A short-lived version adopted in April 1865.' where id = 2492 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1865-1869)', label_en = 'Republic of El Salvador (1865–1869)', notes_fr = 'En juin 1865, le président Francisco Dueñas adopte un drapeau à bandes bleues et blanches et à canton rouge étoilé, inspiré de celui des États-Unis.', notes_en = 'In June 1865 President Francisco Dueñas adopted a flag with blue and white stripes and a starred red canton, inspired by the US flag.' where id = 2493 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1869-1873)', label_en = 'Republic of El Salvador (1869–1873)', notes_fr = 'Le canton compte autant d''étoiles que le pays a de départements.', notes_en = 'The canton had as many stars as the country had departments.' where id = 2494 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1873-1875)', label_en = 'Republic of El Salvador (1873–1875)', notes_fr = 'Nouvelle version du canton étoilé, après la création d''un nouveau département.', notes_en = 'A new version of the starred canton, after a new department was created.' where id = 2495 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1875-1912)', label_en = 'Republic of El Salvador (1875–1912)', notes_fr = 'Dernière version du drapeau rayé à l''américaine, jusqu''au retour aux bandes bleu-blanc-bleu en 1912.', notes_en = 'The last version of the US-style striped flag, until the return to blue-white-blue stripes in 1912.' where id = 2496 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1912-1921)', label_en = 'Republic of El Salvador (1912–1921)', notes_fr = 'En 1912, le Salvador revient aux bandes bleu-blanc-bleu de la fédération centraméricaine, avec ses nouvelles armoiries.', notes_en = 'In 1912 El Salvador returned to the Central American federation''s blue-white-blue stripes, with its new arms.' where id = 2497 and iso_code = 'sv';
update country_flag_history set label_fr = 'Fédération d''Amérique centrale (1921-1922)', label_en = 'Federation of Central America (1921–1922)', notes_fr = 'Éphémère République fédérale d''Amérique centrale réunissant le Salvador, le Guatemala et le Honduras.', notes_en = 'A short-lived Federal Republic of Central America joining El Salvador, Guatemala and Honduras.' where id = 2498 and iso_code = 'sv';
